class Solution { public:int minGroups(vector<vector<int>>& intervals){vector<int> starts,ends;for(auto& interval:intervals){starts.push_back(interval[0]);ends.push_back(interval[1]);}sort(starts.begin(),starts.end());sort(ends.begin(),ends.end());int i=0,j=0,active=0,answer=0;while(i<(int)starts.size()){if(starts[i]<=ends[j]){answer=max(answer,++active);++i;}else{--active;++j;}}return answer;} };
